import { chromium } from "playwright";
import { writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";

const URL = "https://limewire.com/d/F4KwR#C7UtSXeWjQ";
const OUT_DIR = "/tmp/kan153-fetch/download";
mkdirSync(OUT_DIR, { recursive: true });

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  acceptDownloads: true,
  userAgent:
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
});
const page = await context.newPage();

page.on("console", (m) => console.log("[page]", m.type(), m.text()));
page.on("pageerror", (e) => console.log("[pageerror]", e.message));

console.log("navigating");
await page.goto(URL, { waitUntil: "domcontentloaded", timeout: 60000 });
console.log("loaded title:", await page.title());

// Wait a bit for hydration / decryption.
await page.waitForTimeout(3000);

// Look for any download buttons / links.
const html = await page.content();
writeFileSync("/tmp/kan153-fetch/page.html", html, "utf8");
console.log("html bytes:", html.length);

// Try to find the download trigger.
const buttons = await page.$$eval(
  "button, a[role=button], a",
  (els) =>
    els.map((el) => ({
      tag: el.tagName,
      text: (el.textContent || "").trim().slice(0, 80),
      href: el.getAttribute("href") || "",
      cls: el.className?.toString().slice(0, 100) || "",
    })).filter((b) => b.text || b.href),
);
console.log("buttons:", JSON.stringify(buttons.slice(0, 50), null, 2));

await browser.close();

