import { chromium } from "playwright";
import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import path from "node:path";

const URL = "https://limewire.com/d/F4KwR#C7UtSXeWjQ";
const OUT_DIR = "/tmp/kan153-fetch/download";
mkdirSync(OUT_DIR, { recursive: true });

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  acceptDownloads: true,
  userAgent:
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
});
const page = await context.newPage();

page.on("console", (m) => {
  if (m.type() === "error") console.log("[page error]", m.text());
});
page.on("pageerror", (e) => console.log("[pageerror]", e.message));

console.log("navigating");
await page.goto(URL, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForTimeout(2500);

// Dismiss the consent dialog if present.
try {
  const confirm = page.getByRole("button", { name: /confirm|accept|agree/i }).first();
  if (await confirm.isVisible({ timeout: 1500 })) {
    await confirm.click();
    console.log("clicked consent confirm");
    await page.waitForTimeout(1000);
  }
} catch (e) {
  console.log("no consent dialog:", e.message);
}

// Click Download button.
const downloadBtn = page.getByRole("button", { name: "Download", exact: true }).first();
await downloadBtn.waitFor({ state: "visible", timeout: 15000 });

console.log("clicking download, waiting for file event");
const [download] = await Promise.all([
  page.waitForEvent("download", { timeout: 120000 }),
  downloadBtn.click(),
]);

const suggested = download.suggestedFilename();
const target = path.join(OUT_DIR, suggested || "bundle.zip");
console.log("saving to:", target);
await download.saveAs(target);
console.log("saved:", target);

await browser.close();
console.log(existsSync(target) ? "OK" : "MISSING");

