import { chromium } from "playwright";
import { mkdirSync, existsSync } from "node:fs";
import path from "node:path";

const URL = "https://limewire.com/d/F4KwR#C7UtSXeWjQ";
const OUT_DIR = "/tmp/kan153-fetch/download";
mkdirSync(OUT_DIR, { recursive: true });

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  acceptDownloads: true,
  viewport: { width: 1280, height: 900 },
  userAgent:
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
});
const page = await context.newPage();

page.on("pageerror", (e) => console.log("[pageerror]", e.message));

console.log("navigating");
await page.goto(URL, { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForTimeout(2500);

// Dismiss QuantCast (qc-cmp2) consent. Try multiple strategies.
const dismissSelectors = [
  'button.css-1nnj36',                                 // CONFIRM
  'button[mode="primary"]',
  '#qc-cmp2-ui button:has-text("AGREE")',
  '#qc-cmp2-ui button:has-text("Agree")',
  'button:has-text("AGREE")',
  'button:has-text("Disagree")',
  'button:has-text("CONFIRM")',
  'button.qc-cmp2-summary-buttons',
];
for (const sel of dismissSelectors) {
  try {
    const el = page.locator(sel).first();
    if (await el.isVisible({ timeout: 800 }).catch(() => false)) {
      await el.click({ timeout: 2000 }).catch(() => {});
      console.log("clicked:", sel);
      await page.waitForTimeout(800);
    }
  } catch {}
}

// As a fallback: hide the consent container by selector.
await page.evaluate(() => {
  for (const id of ["qc-cmp2-container", "qc-cmp2-main", "qc-cmp2-ui"]) {
    const el = document.getElementById(id);
    if (el) el.style.display = "none";
  }
  document.querySelectorAll(".qc-cmp-cleanslate, .qc-cmp2-container").forEach((e) => {
    e.remove();
  });
});

await page.waitForTimeout(500);

// Click Download button.
const downloadBtn = page.getByRole("button", { name: "Download", exact: true }).first();
await downloadBtn.waitFor({ state: "visible", timeout: 15000 });

console.log("clicking download");
const [download] = await Promise.all([
  page.waitForEvent("download", { timeout: 180000 }),
  downloadBtn.click({ force: true }),
]);

const suggested = download.suggestedFilename();
const target = path.join(OUT_DIR, suggested || "bundle.zip");
console.log("saving to:", target);
await download.saveAs(target);
console.log("saved:", target);

await browser.close();
console.log(existsSync(target) ? "OK" : "MISSING");

